input.sparql:
SELECT ?zp ?ts ?uri WHERE {
  ?z a brick:Zone ; rdfs:label "Basement" .
  ?zp brick:isPointOf ?z ; a brick:OccupancySensor .
  ?zp ref:hasExternalReference ?uri .
  ?uri ref:hasTimeseriesId ?ts .
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
} LIMIT 100

SELECT ?z ?lbl WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label ?lbl .
} LIMIT 100

SELECT ?z ?lbl WHERE {
  ?z a brick:Room ; rdfs:label ?lbl .
} LIMIT 100

SELECT ?z ?lbl WHERE {
  ?z a brick:Floor ; rdfs:label ?lbl .
} LIMIT 100

SELECT ?zp ?ts WHERE {
  ?zp brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01> ; a brick:Occupancy_Sensor .
  ?zp ref:hasTimeseriesId ?ts .
}
